'use client';

import { useState, useEffect } from 'react';
import { DataTable } from '@/components/data-table';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { api } from '@/lib/api';
import { toast } from 'sonner';

interface ContatoCapturado {
  id: string;
  wa_jid: string;
  nome: string | null;
  push_name: string | null;
  is_business: boolean;
  origem: string;
  promovido_cliente_id: number | null;
  created_at: string;
}

export default function ContatosCapturadosPage() {
  const [contatos, setContatos] = useState<ContatoCapturado[]>([]);
  const [loading, setLoading] = useState(true);
  const [selected, setSelected] = useState<string[]>([]);

  useEffect(() => {
    loadContatos();
  }, []);

  async function loadContatos() {
    setLoading(true);
    try {
      const res = await api.get('/api/disparador/contatos');
      setContatos(res.data.items);
    } catch (err) {
      toast.error('Erro ao carregar contatos');
    } finally {
      setLoading(false);
    }
  }

  async function promoverSelecionados() {
    try {
      await api.post('/api/disparador/contatos/promover', {
        ids: selected,
      });
      toast.success(`${selected.length} contatos promovidos para clientes`);
      setSelected([]);
      loadContatos();
    } catch (err) {
      toast.error('Erro ao promover contatos');
    }
  }

  const columns = [
    {
      accessorKey: 'nome',
      header: 'Nome',
      cell: ({ row }) => row.original.nome || row.original.push_name || '-',
    },
    {
      accessorKey: 'wa_jid',
      header: 'WhatsApp ID',
      cell: ({ row }) => (
        <code className="text-xs">{row.original.wa_jid}</code>
      ),
    },
    {
      accessorKey: 'is_business',
      header: 'Tipo',
      cell: ({ row }) => (
        <Badge variant={row.original.is_business ? 'default' : 'secondary'}>
          {row.original.is_business ? 'Business' : 'Pessoal'}
        </Badge>
      ),
    },
    {
      accessorKey: 'origem',
      header: 'Origem',
      cell: ({ row }) => (
        <Badge variant="outline">{row.original.origem}</Badge>
      ),
    },
    {
      accessorKey: 'promovido_cliente_id',
      header: 'Status',
      cell: ({ row }) => (
        row.original.promovido_cliente_id ? (
          <Badge variant="success">Cliente</Badge>
        ) : (
          <Badge variant="warning">Staging</Badge>
        )
      ),
    },
  ];

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center">
        <h1 className="text-2xl font-bold">Contatos Capturados</h1>
        <div className="flex gap-2">
          <Button
            variant="outline"
            onClick={() => api.post('/api/disparador/capturar/contatos')}
          >
            Capturar do WhatsApp
          </Button>
          {selected.length > 0 && (
            <Button onClick={promoverSelecionados}>
              Promover {selected.length} para Cliente
            </Button>
          )}
        </div>
      </div>

      <DataTable
        columns={columns}
        data={contatos}
        loading={loading}
        selectable
        onSelectionChange={setSelected}
      />
    </div>
  );
}
```

