'use client';

import { useState, useEffect } from 'react';
import { DataTable } from '@/components/data-table';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Sheet, SheetContent, SheetHeader, SheetTitle } from '@/components/ui/sheet';
import { api } from '@/lib/api';

interface Grupo {
  id: string;
  wa_jid: string;
  nome: string;
  tipo: 'grupo' | 'comunidade';
  total_membros: number;
  somos_admin: boolean;
}

interface GrupoMembro {
  wa_jid: string;
  is_admin: boolean;
}

export default function GruposPage() {
  const [grupos, setGrupos] = useState<Grupo[]>([]);
  const [membros, setMembros] = useState<GrupoMembro[]>([]);
  const [selectedGrupo, setSelectedGrupo] = useState<Grupo | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadGrupos();
  }, []);

  async function loadGrupos() {
    setLoading(true);
    const res = await api.get('/api/disparador/grupos');
    setGrupos(res.data.items);
    setLoading(false);
  }

  async function loadMembros(grupoId: string) {
    const res = await api.get(`/api/disparador/grupos/${grupoId}/membros`);
    setMembros(res.data.items);
  }

  async function capturarGrupos() {
    await api.post('/api/disparador/capturar/grupos');
    loadGrupos();
  }

  const columns = [
    { accessorKey: 'nome', header: 'Nome' },
    {
      accessorKey: 'tipo',
      header: 'Tipo',
      cell: ({ row }) => (
        <Badge>{row.original.tipo}</Badge>
      ),
    },
    { accessorKey: 'total_membros', header: 'Membros' },
    {
      accessorKey: 'somos_admin',
      header: 'Admin',
      cell: ({ row }) => (
        row.original.somos_admin ? '✓' : '-'
      ),
    },
    {
      id: 'actions',
      cell: ({ row }) => (
        <Button
          size="sm"
          variant="ghost"
          onClick={() => {
            setSelectedGrupo(row.original);
            loadMembros(row.original.id);
          }}
        >
          Ver Membros
        </Button>
      ),
    },
  ];

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center">
        <h1 className="text-2xl font-bold">Grupos</h1>
        <Button onClick={capturarGrupos}>Sincronizar Grupos</Button>
      </div>

      <DataTable columns={columns} data={grupos} loading={loading} />

      <Sheet open={!!selectedGrupo} onOpenChange={() => setSelectedGrupo(null)}>
        <SheetContent>
          <SheetHeader>
            <SheetTitle>Membros de {selectedGrupo?.nome}</SheetTitle>
          </SheetHeader>
          <div className="mt-4 space-y-2">
            {membros.map((m) => (
              <div key={m.wa_jid} className="flex justify-between items-center p-2 border rounded">
                <code className="text-xs">{m.wa_jid}</code>
                {m.is_admin && <Badge>Admin</Badge>}
              </div>
            ))}
          </div>
        </SheetContent>
      </Sheet>
    </div>
  );
}
