from fastapi import APIRouter, Depends, HTTPException
from pydantic import BaseModel
from ..dependencies import get_empresa_context, get_pool
from ...shared.api_key import generate_api_key, hash_api_key

router = APIRouter(prefix="/api/api-keys", tags=["api-keys"])

class CreateKeyRequest(BaseModel):
    name: str
    scopes: list[str] = ['disparador:read', 'disparador:write']
    expires_days: int | None = None  # None = nunca expira

class CreateKeyResponse(BaseModel):
    id: str
    key: str  # Só mostrado uma vez!
    prefix: str
    name: str
    scopes: list[str]
    expires_at: str | None
    created_at: str

class KeyListItem(BaseModel):
    id: str
    prefix: str  # Só o prefixo, não a chave completa
    name: str
    scopes: list[str]
    expires_at: str | None
    last_used_at: str | None
    revoked_at: str | None
    created_at: str

@router.post("", response_model=CreateKeyResponse)
async def create_api_key(
    req: CreateKeyRequest,
    ctx = Depends(get_empresa_context),
    pool = Depends(get_pool),
):
    """Cria nova API key. A chave completa só é exibida aqui!"""
    key, key_hash = generate_api_key(ctx.empresa_id)
    prefix = key.rsplit('_', 1)[0] + '_'  # nxs_<hex>_

    expires_at = None
    if req.expires_days:
        expires_at = datetime.now(timezone.utc) + timedelta(days=req.expires_days)

    async with pool.connection() as conn:
        row = await conn.fetchrow(
            """INSERT INTO empresa_api_key 
               (empresa_id, key_prefix, key_hash, name, scopes, expires_at, created_by_user_id)
               VALUES ($1, $2, $3, $4, $5, $6, $7)
               RETURNING id, created_at""",
            ctx.empresa_id, prefix, key_hash, req.name, req.scopes, expires_at, ctx.user_id
        )

    return CreateKeyResponse(
        id=str(row['id']),
        key=key,  # ÚNICO momento que retorna a chave!
        prefix=prefix,
        name=req.name,
        scopes=req.scopes,
        expires_at=expires_at.isoformat() if expires_at else None,
        created_at=row['created_at'].isoformat(),
    )

@router.get("", response_model=list[KeyListItem])
async def list_api_keys(
    ctx = Depends(get_empresa_context),
    pool = Depends(get_pool),
):
    """Lista todas as API keys da empresa (sem revelar a chave completa)."""
    async with pool.connection() as conn:
        rows = await conn.fetch(
            """SELECT id, key_prefix, name, scopes, expires_at, last_used_at, revoked_at, created_at
               FROM empresa_api_key
               WHERE empresa_id = $1
               ORDER BY created_at DESC""",
            ctx.empresa_id
        )

    return [KeyListItem(
        id=str(r['id']),
        prefix=r['key_prefix'],
        name=r['name'],
        scopes=r['scopes'],
        expires_at=r['expires_at'].isoformat() if r['expires_at'] else None,
        last_used_at=r['last_used_at'].isoformat() if r['last_used_at'] else None,
        revoked_at=r['revoked_at'].isoformat() if r['revoked_at'] else None,
        created_at=r['created_at'].isoformat(),
    ) for r in rows]

@router.post("/{key_id}/revoke")
async def revoke_api_key(
    key_id: str,
    ctx = Depends(get_empresa_context),
    pool = Depends(get_pool),
):
    """Revoga uma API key (não pode ser desfeito)."""
    async with pool.connection() as conn:
        result = await conn.execute(
            """UPDATE empresa_api_key 
               SET revoked_at = NOW()
               WHERE id = $1 AND empresa_id = $2 AND revoked_at IS NULL""",
            key_id, ctx.empresa_id
        )

    if result == 'UPDATE 0':
        raise HTTPException(404, "Chave não encontrada ou já revogada")

    return {"revoked": True}
