## Frontend: /disparador/api-keys/page.tsx

```tsx
'use client';

import { useState, useEffect } from 'react';
import { DataTable } from '@/components/data-table';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { Copy, Key, Trash2 } from 'lucide-react';
import { api } from '@/lib/api';
import { toast } from 'sonner';

export default function ApiKeysPage() {
  const [keys, setKeys] = useState([]);
  const [loading, setLoading] = useState(true);
  const [creating, setCreating] = useState(false);
  const [newKey, setNewKey] = useState<string | null>(null);
  const [form, setForm] = useState({ name: '', expires_days: '' });

  useEffect(() => {
    loadKeys();
  }, []);

  async function loadKeys() {
    setLoading(true);
    const res = await api.get('/api/api-keys');
    setKeys(res.data);
    setLoading(false);
  }

  async function createKey() {
    setCreating(true);
    try {
      const res = await api.post('/api/api-keys', {
        name: form.name,
        expires_days: form.expires_days ? parseInt(form.expires_days) : null,
      });
      setNewKey(res.data.key);
      loadKeys();
    } catch (err) {
      toast.error('Erro ao criar chave');
    } finally {
      setCreating(false);
    }
  }

  async function revokeKey(id: string) {
    if (!confirm('Tem certeza? Esta ação não pode ser desfeita.')) return;
    await api.post(`/api/api-keys/${id}/revoke`);
    toast.success('Chave revogada');
    loadKeys();
  }

  function copyToClipboard(text: string) {
    navigator.clipboard.writeText(text);
    toast.success('Copiado!');
  }

  const columns = [
    { accessorKey: 'name', header: 'Nome' },
    {
      accessorKey: 'prefix',
      header: 'Prefixo',
      cell: ({ row }) => <code>{row.original.prefix}...</code>,
    },
    {
      accessorKey: 'scopes',
      header: 'Escopos',
      cell: ({ row }) => (
        <div className="flex gap-1">
          {row.original.scopes.map((s: string) => (
            <Badge key={s} variant="outline">{s}</Badge>
          ))}
        </div>
      ),
    },
    {
      accessorKey: 'last_used_at',
      header: 'Último Uso',
      cell: ({ row }) => row.original.last_used_at || 'Nunca',
    },
    {
      accessorKey: 'revoked_at',
      header: 'Status',
      cell: ({ row }) => (
        row.original.revoked_at ? (
          <Badge variant="destructive">Revogada</Badge>
        ) : (
          <Badge variant="success">Ativa</Badge>
        )
      ),
    },
    {
      id: 'actions',
      cell: ({ row }) => (
        !row.original.revoked_at && (
          <Button
            size="sm"
            variant="ghost"
            onClick={() => revokeKey(row.original.id)}
          >
            <Trash2 className="h-4 w-4" />
          </Button>
        )
      ),
    },
  ];

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center">
        <h1 className="text-2xl font-bold">Chaves de API</h1>

        <Dialog>
          <DialogTrigger asChild>
            <Button><Key className="mr-2 h-4 w-4" /> Nova Chave</Button>
          </DialogTrigger>
          <DialogContent>
            <DialogHeader>
              <DialogTitle>Criar Nova Chave de API</DialogTitle>
            </DialogHeader>

            {newKey ? (
              <div className="space-y-4">
                <Alert>
                  <AlertDescription>
                    <strong>Atenção:</strong> Esta é a única vez que você verá a chave completa.
                    Copie e guarde em local seguro.
                  </AlertDescription>
                </Alert>
                <div className="flex gap-2">
                  <Input value={newKey} readOnly className="font-mono" />
                  <Button onClick={() => copyToClipboard(newKey)}>
                    <Copy className="h-4 w-4" />
                  </Button>
                </div>
                <Button onClick={() => setNewKey(null)} variant="outline" className="w-full">
                  Fechar
                </Button>
              </div>
            ) : (
              <div className="space-y-4">
                <div>
                  <Label>Nome da chave</Label>
                  <Input
                    value={form.name}
                    onChange={(e) => setForm({ ...form, name: e.target.value })}
                    placeholder="Ex: Integração CRM"
                  />
                </div>
                <div>
                  <Label>Expira em (dias, vazio = nunca)</Label>
                  <Input
                    type="number"
                    value={form.expires_days}
                    onChange={(e) => setForm({ ...form, expires_days: e.target.value })}
                    placeholder="90"
                  />
                </div>
                <Button onClick={createKey} disabled={creating || !form.name} className="w-full">
                  {creating ? 'Criando...' : 'Criar Chave'}
                </Button>
              </div>
            )}
          </DialogContent>
        </Dialog>
      </div>

      <DataTable columns={columns} data={keys} loading={loading} />
    </div>
  );
}
